CREATE OR REPLACE FUNCTION calculate_csi(p_cntref character)
RETURNS numeric AS $$
DECLARE
    v_authenscore numeric;
    v_cntuniqscore numeric;
    v_convnatval numeric;
    v_mediareratio numeric;
    v_txtuniq numeric;
    v_cas numeric;
    v_cms numeric;
    v_csi numeric;
BEGIN
    -- Get authenscore from moderationaction
    SELECT ma.authenscore INTO v_authenscore
    FROM moderationaction ma
    WHERE ma.macntref = p_cntref
    LIMIT 1;

    -- Get contentbehavior scores
    SELECT cb.cntuniqscore, cb.mediareratio INTO v_cntuniqscore, v_mediareratio
    FROM contentbehavior cb
    WHERE cb.cntref = p_cntref
    LIMIT 1;

    -- Get messaginganalysis scores
    SELECT ma.convnatval, ma.txtuniq INTO v_convnatval, v_txtuniq
    FROM messaginganalysis ma
    WHERE ma.msgcntref = p_cntref
    LIMIT 1;

    -- Normalize values to [0,1] if needed (they should already be in range)
    -- Handle NULLs by defaulting to 0.5 (neutral) or handling appropriately
    v_authenscore := COALESCE(v_authenscore, 0.5);
    v_cntuniqscore := COALESCE(v_cntuniqscore, 0.5);
    v_convnatval := COALESCE(v_convnatval, 0.5);
    v_mediareratio := COALESCE(v_mediareratio, 0.5);
    v_txtuniq := COALESCE(v_txtuniq, 0.5);

    -- Calculate CAS = 0.3 * authenscore + 0.3 * cntuniqscore + 0.4 * convnatval
    v_cas := 0.3 * v_authenscore + 0.3 * v_cntuniqscore + 0.4 * v_convnatval;

    -- Calculate CMS = 0.4 * (1 - cntuniqscore) + 0.3 * mediareratio + 0.3 * (1 - txtuniq)
    v_cms := 0.4 * (1 - v_cntuniqscore) + 0.3 * v_mediareratio + 0.3 * (1 - v_txtuniq);

    -- Calculate CSI = 0.7 * (1 - CMS) + 0.3 * CAS
    v_csi := 0.7 * (1 - v_cms) + 0.3 * v_cas;

    RETURN v_csi;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error calculating CSI for %: %', p_cntref, SQLERRM;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

